'use client';
import {useTranslations} from 'next-intl';
import PriceBadge from '@/components/ui/PriceBadge';
import StorePill from '@/components/ui/StorePill';
import type {DashboardStats, Locale, Product} from '@/types/pricewatch';
import {formatPercent, formatPrice, getLowestPrice, getPriceDiff, getTrendDirection} from '@/lib/pricewatch/utils';
export default function DashboardView({products, locale, stats, onOpenProduct}: {products: Product[]; locale: Locale; stats: DashboardStats; onOpenProduct: (product: Product) => void;}) { const t = useTranslations('dashboard'); const topDiff = [...products].sort((a, b) => getPriceDiff(b) - getPriceDiff(a)).slice(0, 5); const recentDrops = products.filter((product) => getTrendDirection(product) === 'down').slice(0, 5); const watchedDrops = products.filter((product) => product.watched && getTrendDirection(product) === 'down').slice(0, 5); return <section className="pw-stack-lg"><div className="pw-card-grid pw-card-grid-stats"><article className="pw-stat-card"><span>{t('stats.tracked')}</span><strong>{stats.tracked}</strong></article><article className="pw-stat-card"><span>{t('stats.priceDrops')}</span><strong>{stats.priceDrops}</strong></article><article className="pw-stat-card"><span>{t('stats.avgSaving')}</span><strong>{formatPercent(stats.avgSavingsPct, locale)}</strong></article><article className="pw-stat-card"><span>{t('stats.foodAlerts')}</span><strong>{stats.foodAlerts}</strong></article></div><div className="pw-two-col"><section className="pw-panel"><div className="pw-section-head"><h2>{t('topDifferences')}</h2></div><div className="pw-mini-table">{topDiff.map((product) => { const lowest = getLowestPrice(product); return <button key={product.id} className="pw-mini-row" onClick={() => onOpenProduct(product)}><div><strong>{product.name}</strong><span>{product.brand}</span></div><div>{lowest ? <StorePill store={lowest.store} /> : null}</div><div>{formatPrice(getPriceDiff(product), locale)}</div></button>; })}</div></section><section className="pw-panel"><div className="pw-section-head"><h2>{t('recentDrops')}</h2></div><div className="pw-list-stack">{recentDrops.map((product) => <button key={product.id} className="pw-list-item" onClick={() => onOpenProduct(product)}><div><strong>{product.name}</strong><span>{product.category}</span></div><PriceBadge label={t('drop')} tone="success" /></button>)}</div></section></div><section className="pw-panel"><div className="pw-section-head"><h2>{t('watchedDrops')}</h2></div><div className="pw-list-stack">{watchedDrops.map((product) => <button key={product.id} className="pw-list-item" onClick={() => onOpenProduct(product)}><div><strong>{product.name}</strong><span>{product.brand}</span></div><span>{formatPrice(getLowestPrice(product)?.price ?? 0, locale)}</span></button>)}</div></section></section>; }
