'use client';
import {Bell, ChartColumnIncreasing, Languages, LayoutDashboard, ListFilter, Moon, Search, Star, Sun} from 'lucide-react';
import clsx from 'clsx';
import {useTranslations} from 'next-intl';
import StorePill from '@/components/ui/StorePill';
import type {Locale, StoreName, ViewName} from '@/types/pricewatch';
const views: Array<{key: ViewName; icon: typeof LayoutDashboard}> = [{key:'dashboard',icon:LayoutDashboard},{key:'results',icon:Search},{key:'watchlist',icon:Star},{key:'categories',icon:ChartColumnIncreasing}];
export type QuickFilterKey = 'watched' | 'drops' | 'offers' | 'lowest90';
export default function AppShell(props:{ locale: Locale; view: ViewName; onViewChange: (view: ViewName) => void; children: React.ReactNode; query: string; onQueryChange: (value: string) => void; stores: StoreName[]; activeStore: string; onStoreChange: (store: string) => void; quickFilters: Record<QuickFilterKey, boolean>; onQuickFilterToggle: (key: QuickFilterKey) => void; alertsCount: number; alertsOpen: boolean; onAlertsToggle: () => void; darkMode: boolean; onDarkModeToggle: () => void; onLocaleToggle: () => void; }) { const {locale,view,onViewChange,children,query,onQueryChange,stores,activeStore,onStoreChange,quickFilters,onQuickFilterToggle,alertsCount,alertsOpen,onAlertsToggle,darkMode,onDarkModeToggle,onLocaleToggle}=props; const t = useTranslations('appShell'); return <div className="pw-shell"><aside className="pw-sidebar"><div className="pw-brand"><div className="pw-brand-mark">PW</div><div><p className="pw-eyebrow">{t('eyebrow')}</p><h1 className="pw-brand-title">Pricewatch v5</h1></div></div><nav className="pw-nav" aria-label={t('nav')}>{views.map(({key,icon:Icon}) => <button key={key} className={clsx('pw-nav-item', view===key && 'is-active')} onClick={() => onViewChange(key)}><Icon size={18} /><span>{t(`views.${key}`)}</span></button>)}</nav></aside><div className="pw-main-wrap"><header className="pw-topbar"><label className="pw-search"><Search size={16} /><input value={query} onChange={(event) => onQueryChange(event.target.value)} placeholder={t('searchPlaceholder')} /></label><div className="pw-toolbar-row"><div className="pw-store-row" role="group" aria-label={t('storeFilter')}><button className={clsx('pw-filter-chip', activeStore==='all' && 'is-active')} onClick={() => onStoreChange('all')}>{t('allStores')}</button>{stores.map((store) => <button key={store} className="pw-store-button" onClick={() => onStoreChange(store)}><StorePill store={store} active={activeStore===store} /></button>)}</div><div className="pw-quick-row"><button className={clsx('pw-filter-chip', quickFilters.watched && 'is-active')} onClick={() => onQuickFilterToggle('watched')}>{t('quick.watched')}</button><button className={clsx('pw-filter-chip', quickFilters.drops && 'is-active')} onClick={() => onQuickFilterToggle('drops')}><ListFilter size={14} />{t('quick.drops')}</button><button className={clsx('pw-filter-chip', quickFilters.offers && 'is-active')} onClick={() => onQuickFilterToggle('offers')}>{t('quick.offers')}</button><button className={clsx('pw-filter-chip', quickFilters.lowest90 && 'is-active')} onClick={() => onQuickFilterToggle('lowest90')}>{t('quick.lowest90')}</button></div></div><div className="pw-actions"><button className={clsx('pw-icon-button', alertsOpen && 'is-active')} onClick={onAlertsToggle} aria-label={t('alerts')}><Bell size={18} />{alertsCount > 0 ? <span className="pw-badge-dot">{alertsCount}</span> : null}</button><button className="pw-icon-button" onClick={onDarkModeToggle} aria-label={t('theme')}>{darkMode ? <Sun size={18} /> : <Moon size={18} />}</button><button className="pw-icon-button" onClick={onLocaleToggle} aria-label={t('language')}><Languages size={18} /><span>{locale === 'en' ? '中' : 'EN'}</span></button></div></header><main className="pw-content">{children}</main></div></div>; }
